"""Apply the verified results to the supplied manuscript without changing its template.

Preserves the author's latest conclusion and MEXT acknowledgement verbatim.
Requires the manuscript supplied as --input; no source files are modified.
"""
from pathlib import Path
import argparse
import pandas as pd
from docx import Document
from docx.shared import Pt
from docx.oxml import OxmlElement
from docx.enum.text import WD_ALIGN_PARAGRAPH

CONCLUSION='Routinely available data can help identify peatland landscapes that warrant closer fire-prevention attention, but they cannot by themselves establish where smoke from those fires reaches communities. During 2020–2025, greater rainfall in the preceding seven days was associated with fewer MODIS detection days within mapped peatland. In Central Kalimantan, the fraction of valid land mapped as burned during August–November 2023 was 3.41 times higher within the peatland map than outside it. Ground sensors also recorded elevated outdoor PM₂.₅ during that season, although its contribution from peatland fires could not be determined. These findings support area-normalized burned-area monitoring alongside rainfall observations when assessing prevention priorities. The next suggested step is to combine peat water-table measurements, land-cover and drainage information, smoke transport, and ground-level PM₂.₅ sensors, then test whether this approach can anticipate hazardous conditions in settlements before future fire seasons.'
ACK='J.F.A. acknowledges support from the Japanese Government (MEXT) Scholarship during the preparation of this manuscript.'

def replace(p,text):
    # Preserve paragraph properties and the original first run's typography.
    if p.runs:
        p.runs[0].text=text
        for r in p.runs[1:]:r.text=''
    else:p.add_run(text)

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--input',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);a=ap.parse_args();out=a.output
    d=Document(a.input);p=d.paragraphs;assert p[4].text=='Abstract' and len(d.tables)==3
    updates={
    5:'Peatland fires in Kalimantan threaten ecosystems and communities, but satellite thermal anomalies alone cannot establish burned area or smoke exposure. We examined whether routinely available observations identify fire-prevention priorities and clarify the evidence needed to assess community exposure. We analysed rainfall and satellite detection days during 2020–2025, compared mapped burned area within and outside a peatland map in Central Kalimantan during August–November 2023, and reanalysed published ground-level fine particulate matter measurements. Provisional 2026 detections were summarized separately. Within mapped peatland, detection-day odds were higher after seven-day rainfall of 0–10 mm than after >100 mm (odds ratio 10.50; approximate 95% confidence interval 6.78–16.27), adjusting for earlier rainfall within cell–year-month strata. The association persisted in satellite, day/night, confidence, and pixel-size sensitivity checks, although cloud-related observation differences remained unresolved. In Central Kalimantan, 4.41% of valid land within the map burned, compared with 1.29% outside it, giving a ratio of 3.41. Mean outdoor fine particulate matter reached 171.2 µg m⁻³ in October. These findings support closer peatland assessment using rainfall and burning normalized by valid land area. Measured air pollution motivates community monitoring; its contribution from particular peatland fires requires additional transport and source information.',
    16:'Descriptive annual MODIS comparisons used 1 January–26 September in each year, based on acquisition dates in coordinated universal time (UTC). The rainfall analysis used the complete 2020–2025 calendar years; provisional 2026 records were excluded from that model. We retained coordinates, satellite, confidence, processing version, and fire type where available. Reported pixel centres were assigned to a province in EPSG:4326 using polygon containment, respecting polygon holes. The ID 6 extract contained 100 unique polygons whose landform attribute included “Gambut”. A live audit on 5 October 2026 returned the same 100 feature IDs and a byte-identical full-geometry GeoJSON. This verifies completeness against the query, not peatland accuracy or complete landscape coverage. Original mapping producer, year, and scale were not specified in the exposed metadata. The annual table includes all thermal-anomaly types because the 2026 NRT file lacks type. The primary historical rainfall outcome used type = 0, meaning presumed vegetation fire. Repeated observations were retained as detections rather than merged into fire events.',
    17:'We summed 24 valid hourly GSMaP rates to obtain daily rainfall in millimetres on a 0.1° grid originating at 108° E and 5° N. Zero-based rows increased southward and columns eastward; grid identifiers were 120 × row + column. Incomplete days were marked missing. Exports included 2–31 December 2019 for the first antecedent windows. We selected 773 cells with centres in a study province and at least one of 25 equally spaced within-cell sample points on ID 6. This selects cells without estimating precise peat area. The panel retained days with no recorded detections. Its binary outcome indicated at least one type = 0 detection within ID 6 on day D. Rainfall windows covered D−7 to D−1 and D−30 to D−8, excluding D and avoiding overlap. A day with no recorded detections was not assumed to be a verified clear-sky, fire-free day.',
    18:'We fitted an exact conditional logistic model stratified by grid cell × year-month. Seven-day rainfall was classified as 0–10, >10–30, >30–60, >60–100, and >100 mm, with >100 mm as the reference. Earlier rainfall entered linearly per 50 mm. Strata with no outcome variation contributed no information to the conditional likelihood. A dynamic-programming implementation evaluated the conditional denominator and score; exact subset enumeration and numerical derivatives checked its core calculations. Approximate intervals used two-way clustered sandwich covariance by cell and year-month (Cameron, Gelbach, & Miller, 2011), multiplied by G/(G−1), where G was the smaller cluster count, and a t critical value with G−1 degrees of freedom. Observation sensitivity checks used Terra, Aqua, daytime, nighttime, confidence ≥80, and scan and track dimensions ≤1.5 km. Additional checks used matched annual windows, July–November, exclusion of 2023, and alternative peat-cell rules. These are specification checks, not predictive validation. A linear working Poisson mean model was retained only as a sensitivity analysis (Table S9).',
    19:'For Central Kalimantan in August–November 2023, we retained the native MCD64A1 grid and classified pixel centres against the geographic provincial and peatland polygons. Native spherical sinusoidal centres were converted analytically to longitude and latitude using the documented radius of 6,371,007.181 m; burned-area values were not resampled. Valid land required nonnegative Burn Date and QA values and QA bits 0 and 1 set. Monthly burned pixels had burn dates within that month. The seasonal denominator included pixels valid in all four months; the numerator counted pixels burned in any month once. Native pixel area converted counts to square kilometres. QA checks excluded shortened mapping periods (bit 2) or special unburned flags (bits 5–7). The previously computed polygon–pixel intersection check was retained as an archived boundary sensitivity result. These alternatives describe classification sensitivity rather than confidence intervals.',
    20:'We analysed the published humidity-adjusted daily sensor series from eight outdoor sites during 16 August–30 November 2023 and calculated an unweighted mean across reporting sites each day. The source checksum matched its Zenodo release. Published processing combined physical channels A/B at most instruments and used physical channel B at PA03/KR_06. Nonmissing released values were stored under field A, with field B empty; we interpreted them as processed concentrations rather than a physical-channel assignment. Checks used the complete two-site network and excluded KR_06. CAMS values were converted from kg m⁻³ to µg m⁻³ and averaged over eight three-hourly values per complete day. All sites selected one 0.75° model cell. Sensor averaging timezone was unspecified, so we compared unchanged date labels with CAMS daily means in UTC and Western Indonesian Time (WIB; UTC+7), and separately shifted sensor labels ±1 day. Daily-level and first-difference Spearman correlations were descriptive. They did not identify smoke sources. Python scripts, source checksums, the daily panel, and the supplementary tables retain reproduction details.',
    22:'MODIS detections varied substantially among matched annual periods (Figure 2; Table 1). The largest historical count occurred in 2023, with 14,073 detections across the five provinces and 2,242 within ID 6. Across 2020–2025, 4,076 of 35,519 detections (11.5%) fell within the peatland map. The provisional 2026 extract contained 53,476 detections, including 17,934 within ID 6 (33.5%). Figure 2 compares the equivalent 2023 and provisional 2026 calendar windows. Detections occur both within and outside ID 6, with concentrations on mapped peatland in Central and West Kalimantan. The Terra share of recorded detections changed from 22.1% in 2023 to 41.2% in 2026 (Table S2), so these records do not establish equivalent observation opportunities or an independent measure of increased fire severity. Counts retain the processing difference and describe approximate pixel centres; they do not measure burned area or peat-soil combustion (NASA, n.d.; Tansey et al., 2008).',
    24:'The full-year rainfall panel contained 1,694,416 grid-days, including 3,059 days with type = 0 detections. Of 55,656 cell–year-month strata, 1,420 informative strata supplied 43,283 observations to the primary model, with 420 cell and 70 year-month clusters (Table S10). Relative to >100 mm of preceding seven-day rainfall, detection-day odds ratios were 10.50 (approximate 95% interval 6.78–16.27) for 0–10 mm, 5.26 (2.97–9.34) for >10–30 mm, 2.57 (1.31–5.04) for >30–60 mm, and 1.50 (0.90–2.51) for >60–100 mm (Figure 3; Table 2). The earlier-window term was 0.94 per 50 mm (0.79–1.12). The 0–10 mm contrast remained above one in Terra-only, Aqua-only, day, night, high-confidence, and smaller-pixel checks (Figure S2; Tables S3–S4). These estimates describe recorded detection odds within strata, not ratios of burned area or fire-event frequency.',
    25:'The rainfall pattern is compatible with a drying pathway, but satellite precipitation does not measure peat moisture or groundwater. Taufik et al. (2017) showed that hydrological drought adds information to burned-area prediction in Borneo. Severe fire-weather conditions can also arise under different ENSO phases (Lam et al., 2026). Local rainfall and hydrology therefore remain relevant alongside seasonal climate indices. NASA documentation identifies cloud and thick smoke as causes of missed fire detections (NASA, 2024). Positive-only FIRMS CSVs do not provide cloud, unknown, non-fire, or missing-observation pixels. Satellite and detection-subset checks consequently cannot remove cloud-dependent observation bias. Drainage, vegetation, and ignition were also not isolated by the model. We interpret the association as rainfall versus observed detection days and do not attribute it to anthropogenic climate change.',
    26:'The 2023 case study provided a spatial basis for prevention priorities using valid land-area denominators. Within ID 6, 1,044.1 km² was mapped as burned, representing 4.41% of comparable valid land, compared with 1,653.5 km² and 1.29% outside it (Table 3). The ratio of burned fractions was 3.41. Raw-raster recalculation reproduced the seasonal pixel counts; the ratio was 3.29 after excluding shortened mapping periods and 3.39 after excluding special unburned flags (Tables S5–S6). The archived polygon–pixel intersection result was 3.60. October had the highest monthly fraction in both classes (Figure 4A). Although absolute burned area was greater outside ID 6, burning was more concentrated relative to valid land within it. This supports closer assessment in this province and season without establishing universal peatland dominance or combustion of underlying peat.',
    28:'The published sensor network documented substantial outdoor air pollution during the same season. Means across daily reporting-site averages were 40.1 µg m⁻³ for 16–31 August, 100.3 in September, 171.2 in October, and 47.0 in November (Figure 4B; Table S7). October remained highest when a fixed two-site network was used (156.4 µg m⁻³) and KR_06 was excluded (171.9 µg m⁻³). Across 107 paired days, daily burned area within and outside ID 6 correlated with sensor PM₂.₅ (Spearman ρ = 0.784 and 0.657); first-difference correlations were approximately 0.067 and −0.074 (Table S8). This broad seasonal correspondence did not identify which mapped areas contributed the particles.',
    29:'CAMS followed much of the temporal ordering of the sensor series (Spearman ρ = 0.882), but its UTC mean for the shared model cell was 187.8 µg m⁻³, compared with 96.9 µg m⁻³ across daily sensor means. Local WIB grouping gave a CAMS mean of 187.9 and a daily-level correlation of 0.881. First-difference correlations were 0.383 under UTC and 0.204 under WIB. The mean difference and seasonal correspondence persisted, while daily changes were more sensitive to averaging convention (Table S8; Figure S3). These comparisons support local evaluation before using model concentrations for population exposure screening. The sensors do not represent every settlement or personal time indoors. Graham, Spracklen, et al. (2024) combined the original campaign with regional modelling and exposure information. Our reanalysis adds the mapped burning contrast while retaining a distinction between prevention evidence and source-specific exposure.',
    30:'Matched descriptive periods, full-year historical modelling, zero-detection observations, valid-area denominators, and detection-subset checks improve comparability. The observation scales nevertheless differ: rainfall covers six calendar years, whereas burned-area and sensor results cover one province and one season. MCD64A1 uses MODIS active-fire information, so agreement with FIRMS is complementary evidence rather than independent validation (Giglio et al., 2018). Sustainable conservation monitoring could combine rainfall with peat water table, vegetation, and drainage observations before ignition, then connect fire activity with transport modelling and locally evaluated PM₂.₅ sensors. Testing that combination in withheld seasons, including warning lead time and false alerts, remains a future research agenda rather than a prediction system demonstrated here.',
    32:CONCLUSION,34:ACK,
    58:'Figure 2. Spatial distribution of MODIS thermal-anomaly detections relative to BIG ID 6. Green denotes mapped peatland; red and black points have reported pixel centres within and outside ID 6. Panels A and B show 1 January–26 September 2023 and provisional 2026, respectively. Both panels use the same display settings. Repeated detections may overlap. These maps do not show burned area or area-normalized risk.',
    59:'Figure 3. Adjusted odds ratios for a recorded MODIS vegetation-fire detection day by preceding seven-day rainfall category, 2020–2025. The reference is >100 mm. The exact conditional logistic model conditions on cell × year-month and adjusts for rainfall during D−30 to D−8. Bars show approximate two-way cluster intervals. They do not account for unmeasured clear-sky observation availability.',
    62:'Table 2. Conditional logistic associations between antecedent rainfall and a MODIS vegetation-fire detection day during the complete 2020–2025 calendar years.',
    81:'Entries are odds ratios with approximate 95% intervals, conditional on cell × year-month and adjusted for the other rainfall window. Seven-day rainfall uses >100 mm as reference. Earlier rainfall is linear per additional 50 mm. Intervals use two-way clustered covariance with a common finite-cluster multiplier and t critical value. Observation and specification checks are in Tables S3–S4; the working Poisson sensitivity is in Table S9.',
    84:'The denominator includes pixels valid in all four months; pixels burned repeatedly are counted once. The within/outside ID 6 ratio is 3.41. QA sensitivities are 3.29 and 3.39; the archived polygon–pixel intersection result is 3.60. These alternatives are not confidence limits. Surface burning within ID 6 does not establish peat-soil combustion.'}
    for i,text in updates.items():replace(p[i],text)
    replace(p[14],p[14].text.replace(' ERA5 10 m wind components supported an exploratory directional comparison (Hersbach et al., 2020).',''))
    for i,j in [(69,58),(72,59),(80,62)]:replace(p[i],updates[j])
    # Insert NASA documentation near the existing institutional reference.
    new=OxmlElement('w:p');p[53]._p.addnext(new)
    from docx.text.paragraph import Paragraph
    ref=Paragraph(new,p[53]._parent);ref.style=p[53].style;ref.add_run('National Aeronautics and Space Administration. (2024). The impact of cloud on active fire detections. FIRMS Earthdata Wiki. Retrieved October 5, 2026, from https://wiki.earthdata.nasa.gov/spaces/FIRMS/blog/2024/08/07/382276882/The+Impact+of+Cloud+on+Active+Fire+Detections')
    # Remove an uncited wind reference; no new wind inference is included.
    p[46]._element.getparent().remove(p[46]._element)
    table=d.tables[1]
    while len(table.rows)>6:table._tbl.remove(table.rows[-1]._tr)
    headers=['Rainfall predictor','Comparison','Odds ratio (95% interval)']
    for c,v in zip(table.rows[0].cells,headers):c.text=v
    results=pd.read_csv(out/'tables/Table_2_Rainfall_Primary.csv')
    for row,(_,r) in zip(table.rows[1:],results.iterrows()):
        vals=['Preceding seven days' if r.term!='Earlier rainfall, per 50 mm' else 'Earlier 23 days',r.term+' mm versus >100 mm' if r.term!='Earlier rainfall, per 50 mm' else 'Per additional 50 mm',f'{r.odds_ratio:.2f} ({r.ci95_low:.2f}–{r.ci95_high:.2f})']
        for cell,v in zip(row.cells,vals):
            cell.text=v
            for paragraph in cell.paragraphs:
                for run in paragraph.runs:run.font.name='Times New Roman';run.font.size=Pt(10)
    table.autofit=False
    available=d.sections[-1].page_width-d.sections[-1].left_margin-d.sections[-1].right_margin
    for j,share in enumerate([.32,.36,.32]):
        table.columns[j].width=int(available*share)
        for i,row in enumerate(table.rows):
            row.cells[j].width=int(available*share)
            for paragraph in row.cells[j].paragraphs:
                paragraph.alignment=WD_ALIGN_PARAGRAPH.LEFT
                for run in paragraph.runs:
                    run.font.name='Times New Roman';run.font.size=Pt(10);run.bold=(i==0)
    names=['Figure_1_Peatland_Map_Coverage','Figure_2_MODIS_ID6_2023_2026','Figure_3_Rainfall_Detection_Odds','Figure_4_Burning_and_PM25_2023']
    for image,name in zip(d.inline_shapes,names):
        rid=image._inline.graphic.graphicData.pic.blipFill.blip.embed
        part=d.part.related_parts[rid];part._blob=(out/'figures'/f'{name}.png').read_bytes()
        from PIL import Image
        with Image.open(out/'figures'/f'{name}.png') as im:ratio=im.height/im.width
        image.height=int(image.width*ratio)
    path=out/'manuscript/Kalimantan_Manuscript_Consistency_Checked.docx';d.save(path)
    alltext='\n'.join(x.text for x in d.paragraphs)
    assert CONCLUSION in alltext and ACK in alltext
    assert '1,249,168' not in alltext and 'incidence rate ratio 0.316' not in alltext
    (out/'manuscript/Manuscript_Consistency_Checked.txt').write_text(alltext,encoding='utf8')
    print(path)

if __name__=='__main__':main()
